/* ===== Калькулятор (ця ж копія вставлена в index.html) ===== */
const ceilE=x=>Math.ceil(x-1e-7);
const withRes=(n,r)=>{const x=n*r/100;return n+(x<0.5-1e-9?0:ceilE(x))};           // 11.000000000000002 → 11, а не 12
const floorE=x=>Math.floor(x+1e-7);         // 3.9999999 → 4
// листи/плитка a×b (a — вздовж W): цілі + крайній стовпчик + крайній ряд + кут; обрізки по краю використовуються повторно
function gridCount(W,H,a,b){
 const Fw=floorE(W/a),rw=W-Fw*a>1e-6?W-Fw*a:0,Fh=floorE(H/b),rh=H-Fh*b>1e-6?H-Fh*b:0;
 let n=Fw*Fh;
 if(rw)n+=ceilE(Fh/Math.max(1,floorE(a/rw)));
 if(rh)n+=ceilE(Fw/Math.max(1,floorE(b/rh)));
 if(rw&&rh)n+=1;
 return{n}}
// рулон/довга смуга шириною w, довжиною L: смуги йдуть вздовж H, кількість смуг — по W
function stripCount(W,H,w,L){
 const cols=ceilE(W/w),k=floorE(H/L),hr=H-k*L>1e-6?H-k*L:0;
 const n=cols*k+(hr?ceilE(cols/Math.max(1,floorE(L/hr))):0);
 return{n,cols,used:cols*H,L,len:H}}
/* el={a,b,per}: розмір одного шматка (м), per — шматків в одиниці продажу (для наборів)
   inp={W,H,S,open,r}: стіна W×H (м) або площа S (м²), open — вікна/двері (м²), r — запас (%) */
function calcNeed(el,inp){
 const area=el.a*el.b,per=el.per||1,r=Math.max(0,inp.r||0);
 const dims=inp.W>0&&inp.H>0,gross=dims?inp.W*inp.H:(inp.S||0);
 const open=Math.min(Math.max(inp.open||0,0),gross*.9),S=gross-open;
 if(!(S>0)||!(area>0))return null;
 const ideal=ceilE(S/area),roll=Math.max(el.a,el.b)>=2.5;
 let pieces=ideal,how='area',recPieces=withRes(ideal,r),strip=null;
 if(dims){
  const s=Math.min(el.a,el.b),l=Math.max(el.a,el.b);
  if(roll){
   const o=[stripCount(inp.W,inp.H,s,l),stripCount(inp.H,inp.W,s,l)].sort((x,y)=>x.n-y.n)[0];
   let n=o.n,used=o.used;if(open>0){n=Math.max(ceilE(n*S/gross),1);used*=S/gross}
   pieces=Math.max(n,ideal);how='strip';strip=o;
   // запас для рулонів: якщо в куплених рулонах лишається ≥ r% довжини — ще один рулон не потрібен
   recPieces=pieces*o.L-used>=used*r/100-1e-9?pieces:pieces+ceilE((used*(1+r/100)-pieces*o.L)/o.L);
  }else{
   let n=Math.min(gridCount(inp.W,inp.H,el.a,el.b).n,gridCount(inp.W,inp.H,el.b,el.a).n);
   if(open>0)n=ceilE(n*S/gross);
   pieces=Math.max(n,ideal);how='grid';recPieces=withRes(pieces,r);
  }
 }
 const units=ceilE(pieces/per),rec=Math.max(units,ceilE(recPieces/per));
 return{S,ideal,pieces,units,rec,how,roll,strip,noRes:r>0&&rec==units}}

