// відсутній на сторінці елемент → «порожній» div, щоб спільний код працював на будь-якій сторінці
const $=s=>document.querySelector(s)||document.createElement('div'),$$=s=>[...document.querySelectorAll(s)];
const PAGE=window.PAGE||{},LAND=!!PAGE.cats,HOMEURL=LAND?'./':'';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang='uk';try{lang=JSON.parse(localStorage.getItem('lang')||'null')||((navigator.language||'').startsWith('ru')?'ru':'uk')}catch(e){}
if(lang!='ru')lang='uk';
const LI=()=>lang=='ru'?1:0;
const t=(k,v)=>{let s=(K[k]||[k])[LI()]||K[k][0];if(v)for(const x in v)s=s.split('{'+x+'}').join(v[x]);return s};
const money=n=>Math.round(n).toLocaleString('uk-UA').replace(/ /g,' ')+' ₴';
const num=s=>parseFloat(String(s).replace(/[^\d.,]/g,'').replace(',','.'))||0;
const fmt=(n,d=2)=>(+n.toFixed(d)).toLocaleString('uk-UA');
const ls={get:(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch(e){return d}},set:(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}}};
const catBy=Object.fromEntries(CATS.map(c=>[c[0],c]));
const cname=s=>VIRT[s]?VIRT[s][lang]:catBy[s]?catBy[s][LI()?3:2]:s;
const gname=g=>{const x=GROUPS.find(x=>x[0]==g);return x?x[LI()?2:1]:''};
const cgroup=s=>VIRT[s]?VIRT[s].g:catBy[s]?catBy[s][1]:'';
const catsOf=s=>VIRT[s]?VIRT[s].inc:[s];
const SCOPE=LAND?new Set(PAGE.cats.flatMap(catsOf)):null;
const inScope=c=>!LAND||catsOf(c).every(x=>SCOPE.has(x));

let all=[],byId=new Map(),counts={},view={},shown=CFG.step,sort='',onlyAv=false,onlySale=false,cart=ls.get('cart',{}),cust=ls.get('cust',{}),loaded=false;

function classify(title){const l=title.toLowerCase();return CATS.find(c=>c[4].test(l))[0]}
// розмір одного елемента з назви: 700х770х5мм, 0,45х10м, 60cm*10m, 0,6*3m*2мм → [a,b] у метрах
function dimsOf(title){
 const x=title.toLowerCase().replace(/(\d),(\d)/g,'$1.$2').replace(/[x*×]/g,'х').replace(/(\d)\s*mm/g,'$1мм').replace(/(\d)\s*cm/g,'$1см').replace(/(\d)\s*m\b/g,'$1м');
 const m=x.match(/(\d+(?:\.\d+)?)\s*(мм|см|м)?\s*х\s*(\d+(?:\.\d+)?)\s*(мм|см|м)?(?:\s*х\s*\d+(?:\.\d+)?\s*(мм|см|м)?)?/);if(!m)return null;
 const k={мм:.001,см:.01,м:1};let ua=m[2]||m[4]||m[5],ub=m[4]||m[5]||m[2];const a=+m[1],b=+m[3];
 if(!ua){ua=ub=(Math.max(a,b)>=100?'мм':'см')}
 const A=a*k[ua],B=b*k[ub];return A*B>.004&&A*B<60?[A,B]:null}
// розмір з характеристик (Ширина/Довжина/Висота в мм) — точніший за назву
function dimsOfPar(P){const v=['Ширина','Довжина','Висота'].map(k=>num(P[k])).filter(x=>x>0);return v.length>=2&&v[0]>=20&&v[1]>=20?[v[0]/1000,v[1]/1000]:null}
function elOf(name,P,cat){
 if(!CALCG.has(catBy[cat][1])&&cat!='ekoshkira')return null;
 let d=dimsOfPar(P)||dimsOf(name);
 if(!d){const pa=num(P['Площа, що покривається панеллю']);if(pa>0)d=[Math.sqrt(pa),Math.sqrt(pa)];else return null}
 const qty=parseInt(P['Кількість в упаковці'],10)||parseInt((name.match(/\((\d+)\s*шт\)|(\d+)\s*рулон/)||[]).slice(1).find(Boolean),10)||1;
 const isSet=/набір|комплект/i.test(name)&&!/ціна за 1 шт/i.test(name);
 // набір з N шт/рулонів: якщо в назві вказано загальний розмір (напр. 700х1400 для 2 панелей 700х700) — беремо розмір з характеристик
 return{a:d[0],b:d[1],per:isSet?qty:1,pack:!isSet&&qty>1?qty:0}}

/* ---------- завантаження XML ---------- */
function parse(xml){
 const d=new DOMParser().parseFromString(xml,'text/xml');
 const nodes=d.getElementsByTagName('item').length?d.getElementsByTagName('item'):d.getElementsByTagName('offer');
 const out=[];
 for(let i=0;i<nodes.length;i++){
  const e=nodes[i],f={},imgs=[],par=[];
  for(const c of e.children){const n=c.localName.toLowerCase();
   if(n=='additional_image_link'||n=='picture'){const v=c.textContent.trim();if(v)imgs.push(v)}
   else if(n=='product_detail'){let a='',b='';for(const x of c.children){const l=x.localName;if(l=='attribute_name'||l=='product_name')a=x.textContent.trim();if(l=='attribute_value'||l=='product_value')b=x.textContent.trim()}if(a&&b)par.push([a,b])}
   else if(n=='param'){par.push([c.getAttribute('name'),c.textContent.trim()])}
   else if(!(n in f))f[n]=c.textContent.trim()}
  const raw=f.title||f.name||f.model||'';const price=num(f.price||f.sale_price);if(!raw||!price)continue;
  const m=raw.match(/\s*(SW-\d+)\s*$/i),sku=m?m[1]:(f.vendorcode||f.mpn||''),name=m?raw.slice(0,m.index).trim():raw;
  const id=String(f.id||e.getAttribute('id')||'p'+i);
  const img=f.image_link||imgs.shift()||'';if(f.image_link&&imgs[0]==img)imgs.shift();
  const avs=(f.availability||e.getAttribute('available')||'in stock').toLowerCase();
  const av=!/out|false|^0|нема|нет|ні$|preorder/.test(avs);
  const cat=classify(name),P=Object.fromEntries(par),el=elOf(name,P,cat),area=el?el.a*el.b*el.per:0;
  out.push({id,name,sku,price,old:num(f.sale_price&&f.price?f.price:0),img,imgs:[img,...imgs].filter(Boolean).slice(0,8),av,cat,area,el,P,brand:f.brand||'',color:f.color||'',par,desc:f.description||'',sale:/уцінк|уценк/i.test(name),n:parseInt((sku.match(/\d+/)||['0'])[0],10)||0,i,
   key:(name+' '+sku+' '+id+' '+cname(cat)+' '+catBy[cat][3]+' '+(f.color||'')).toLowerCase().replace(/[x*×]/g,'х')});
 }
 return out}
function load(){
 $('#msg').innerHTML='';
 const go=u=>fetch(u,{cache:'no-cache'}).then(r=>{if(!r.ok)throw 0;return r.text()});
 go(CFG.xml).catch(()=>go(CFG.xmlBackup)).then(x=>{
  all=parse(x);if(!all.length)throw 0;
  byId=new Map(all.map(p=>[p.id,p]));counts={};all.forEach(p=>counts[p.cat]=(counts[p.cat]||0)+1);
  loaded=true;[decorateDir,fillWall,fillNew,drawKB].forEach(f=>safe(f,f.name));route(false);if(location.hash)setTimeout(()=>{const x=$(location.hash);x&&x.scrollIntoView()},60);
 }).catch(()=>{$('#grid').innerHTML='';$('#msg').innerHTML=`<div class="empty">${t('err')}<br><button class="btn" data-a="retry">${t('retry')}</button></div>`});
}

/* ---------- маршрути: ?c= ?g= ?q= ?p= ---------- */
function readURL(){const u=new URLSearchParams(location.search);return{c:u.get('c')||'',g:u.get('g')||'',q:u.get('q')||'',p:u.get('p')||''}}
function makeURL(v){const u=new URLSearchParams();if(v.c)u.set('c',v.c);else if(v.g)u.set('g',v.g);if(v.q)u.set('q',v.q);if(v.p)u.set('p',v.p);const s=u.toString();return location.pathname+(s?'?'+s:'')}
function nav(v,scroll=true){view={c:'',g:'',q:'',p:'',...v};history.pushState(view,'',makeURL(view));shown=CFG.step;render();if(scroll&&(view.c||view.g||view.q))$('#catalog').scrollIntoView({block:'start'})}
function route(scroll){view=readURL();shown=CFG.step;if(view.q){$('#q').value=view.q;$('#q2').value=view.q}render();if(view.p)openP(view.p,false);else if(pdOpen())$('#pd').close();if(scroll&&(view.c||view.g))$('#catalog').scrollIntoView()}
addEventListener('popstate',()=>route(false));

/* ---------- пошук ---------- */
const SYN=[[/^панел/,'панел'],[/^плен|^плёнк|^пленк/,'плівк'],[/^обо/,'шпалер'],[/^зеркал/,'дзеркал'],[/^ковролин/,'ковролін'],[/^винил/,'вінілов'],[/^экокож|^экокоже/,'екошкір'],[/^ковр/,'килим'],[/^мебел/,'мебл'],[/^плинтус/,'плінтус'],[/^пол$/,'підлог'],[/^мозаик/,'мозаї'],[/^стен/,'стін'],[/^самокле/,'самоклеюч'],[/^кирпич/,'цегл'],[/^дерев/,'дерев'],[/^мрамор/,'мармур'],[/^камен/,'камін'],[/^бел/,'біл'],[/^черн/,'чорн'],[/^сер/,'сір'],[/^штукатур/,'штукатурк'],[/^контейнер/,'контейнер'],[/^детск/,'дитяч']];
function words(q){return q.toLowerCase().replace(/[x*×]/g,'х').split(/[\s,]+/).filter(w=>w.length>1||/\d/.test(w)).map(w=>{for(const[r,s]of SYN)if(r.test(w))return s;return w.length>5?w.slice(0,w.length-1):w})}

/* ---------- список ---------- */
function list(){
 let L=all;
 if(view.c){const cs=new Set(catsOf(view.c));L=L.filter(p=>cs.has(p.cat))}
 else if(view.g)L=L.filter(p=>catBy[p.cat][1]==view.g);
 else if(LAND&&!view.q)L=L.filter(p=>SCOPE.has(p.cat));
 if(view.q){const W=words(view.q);L=L.filter(p=>W.every(w=>p.key.includes(w)))}
 if(onlyAv)L=L.filter(p=>p.av);
 if(onlySale)L=L.filter(p=>p.sale);
 const f={a:(x,y)=>x.price-y.price,d:(x,y)=>y.price-x.price,n:(x,y)=>y.n-x.n}[sort];
 const ci=LAND&&!view.c&&!f?p=>PAGE.cats.findIndex(c=>catsOf(c).includes(p.cat)):()=>0;
 return [...L].sort((x,y)=>(y.av-x.av)||(f?f(x,y):(ci(x)-ci(y))||x.i-y.i))}
const ppm=p=>p.area&&p.area<40?`<span class="ppm">≈ ${money(p.price/p.area)}/м²</span>`:'';
const href=p=>'?p='+encodeURIComponent(p.id);
const card=p=>`<article class="card"><a class="im" href="${href(p)}" data-p="${esc(p.id)}"><img loading="lazy" decoding="async" src="${esc(p.img)}" alt="${esc(p.name)}" onerror="this.style.opacity=0">${!p.av?`<span class="badge out">${t('outst')}</span>`:p.sale?`<span class="badge">${t('sale')}</span>`:''}</a><div class="bd"><h3><a href="${href(p)}" data-p="${esc(p.id)}">${esc(p.name)}</a></h3><div class="meta"><span>${esc(cname(p.cat))}</span><span>${esc(p.sku)}</span></div><div class="price">${money(p.price)}${ppm(p)}</div><div class="ab">${p.av?`<button class="btn" data-add="${esc(p.id)}">${t('add')}</button><button class="btn ghost" data-p="${esc(p.id)}" data-f="1">${t('q1b')}</button>`:`<button class="btn ghost" data-askp="${esc(p.id)}">${t('ask')}</button>`}</div></div></article>`;

function render(){
 const home=!view.c&&!view.g&&!view.q;
 if(LAND)return renderLand();
 document.body.classList.toggle('is-home',home);
 $('#hero').hidden=!home;fillSeen(home);$('#dir').hidden=!home;$('#kb').hidden=!!view.c;$('#newin').hidden=!home||!$('#newGrid').children.length;
 // заголовок
 const title=view.c?cname(view.c):view.g?gname(view.g):view.q?t('srres',{q:view.q}):t('allh');
 const h=$('#ctitle');const tag=home?'H2':'H1';if(h.tagName!=tag){const n=document.createElement(tag);n.id='ctitle';h.replaceWith(n)}
 $('#ctitle').textContent=title;
 // хлібні крихти
 const cr=[[t('home'),'./']];const g=view.c?cgroup(view.c):view.g;
 if(g)cr.push([gname(g),'?g='+g]);if(view.c)cr.push([cname(view.c),'?c='+view.c]);
 $('#crumbs').innerHTML=home?'':cr.map(([n,u],i)=>`<span>${i<cr.length-1?`<a href="${u}" data-nav>${esc(n)}</a>`:esc(n)}</span>`).join('');
 drawSide();drawSubs(g);
 if(!loaded)return;
 const L=list();
 $('#ccount').textContent=L.length+' '+t('items');
 $('#grid').innerHTML=L.slice(0,shown).map(card).join('');
 $('#more').hidden=L.length<=shown;
 $('#msg').innerHTML=L.length?'':`<div class="empty">${t('none')}<br><button class="btn" data-a="askq">${t('askm')}</button> <button class="btn ghost" data-a="reset">${t('reset')}</button></div>`;
 $$('[data-a=clr]').forEach(b=>b.hidden=!view.q);
 seo(L,title,g);
}
