 const cr=[[t('home'),'./'],[PAGE.name,location.pathname]];if(view.c)cr.push([cname(view.c),'']);
 $('#crumbs').innerHTML=cr.map(([n,u],i)=>`<span>${i<cr.length-1?`<a href="${u}"${i?' data-nav':''}>${esc(n)}</a>`:esc(n)}</span>`).join('');
