 $$('[data-lc]').forEach(a=>{const n=cnt(a.dataset.lc);const i=a.querySelector('i');if(i)i.textContent=n||'';if(loaded&&!n)a.hidden=true});
 if(!loaded)return;
 const L=list();
 $('#ccount').textContent=L.length+' '+t('items');
 $('#grid').innerHTML=L.slice(0,shown).map(card).join('');
