const safe=(f,n)=>{try{f()}catch(e){console.error('[Samostroy] '+n,e)}};
safe(()=>$('#yr').textContent=new Date().getFullYear(),'year');
safe(buildMega,'menu');
safe(()=>setLang(lang),'lang');
safe(()=>{view=readURL();render()},'render');
load();
